			rf := &refunds[ri]
			rk := balanceKey{rf.Account, rf.Asset}
			cur := net[rk]
			if rf.Charged > cur {
				return ledgerError(ErrCorrupt, "refund %q exceeds charged amount for %s/%s at its time", rf.ID, rf.Account, rf.Asset)
			}
			net[rk] = cur - rf.Charged
