	// 此处兜底，任何未被消费的退款都视为顺序损坏。
	if len(buckets[0]) != 0 {
		return ledgerError(ErrCorrupt, "refund %q precedes every settlement", refunds[buckets[0][0]].ID)
	}

	// 交错重放后的末态必须与文件中的最终余额逐组合一致。
	for k, start := range initial {
		got := start - net[k]
		if want, present := final[k]; !present || got != want {
			return ledgerError(ErrCorrupt, "final balance mismatch for %s/%s: replay %d, file %v", k.account, k.asset, got, want)
		}
	}
	for k := range final {
		if _, ok := initial[k]; !ok {
			return ledgerError(ErrCorrupt, "final balance contains %s/%s absent from initial balances", k.account, k.asset)
		}
	}
	return nil
}

// checksumHex 返回 data 的 sha256 十六进制摘要，作为文档完整性凭证。
func checksumHex(data []byte) string {
	sum := sha256.Sum256(data)
	return hex.EncodeToString(sum[:])
}

package payflow

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"math/big"
	"sort"
)

// 离线流水对账：把外部支付渠道提供的有序流水与本地账本逐笔核对。
// 对账是只读操作，不改变余额、历史或账本文件。
//
// 逐条结果（保持输入顺序）有五种：
//   - matched：编号命中一条成功记录，且全部核对字段一致；
//   - field_mismatch：编号命中成功记录，但至少一个字段不同（逐个列出差异）；
//   - missing_in_ledger：账本中没有该编号的成功记录；
//   - duplicate：同一(kind,id)在输入中出现多次，整组全部标为重复并附全部
//     输入位置，不再判断字段差异，也不再把对应账本记录列为缺失；
//   - out_of_scope：命中同类型同编号的成功记录，但该记录的成功序号不在本次
//     核对范围内（after < seq <= through）。不比较字段、不计入流水侧汇总；
//     该编号在流水中出现多次时全部按此状态处理（优先于整组重复）。
//
// 付款编号与退款编号分别匹配，同名也不会混为一笔。只核对成功记录：
// 已退款的付款仍按原扣款核对，退款单独核对。账本中没有任何对应流水的入选
// 记录另列缺失（先按付款成功顺序，再按退款成功顺序）。范围只影响记录是否
// 参加核对，不切断关联：入选退款仍可指向范围外付款，入选付款仍携带范围外
// 退款的信息。

const (
	ReconMatched         = "matched"
	ReconFieldMismatch   = "field_mismatch"
	ReconMissingInLedger = "missing_in_ledger"
	ReconDuplicate       = "duplicate"
	ReconOutOfScope      = "out_of_scope"
)

// amountJSON 是必须提供、且为 int64 整数的金额。
// 使用指针 + 自定义解码区分“缺省/null/非数字/越界”等情形。
type amountJSON struct {
	v int64
}

func (a *amountJSON) UnmarshalJSON(data []byte) error {
	if string(data) == "null" {
		return fmt.Errorf("amount must be an int64 integer, not null")
	}
	dec := json.NewDecoder(bytes.NewReader(data))
	var v int64
	if err := dec.Decode(&v); err != nil {
		return err
	}
	// 单个数字字面量必须恰好结束。
	if tok, err := dec.Token(); err != io.EOF {
		if err == nil {
			return fmt.Errorf("invalid integer amount (unexpected token %v)", tok)
		}
		return err
	}
	a.v = v
	return nil
}

// flowEntryJSON 是流水的严格解码形态。未知字段按标准库惯例忽略。
type flowEntryJSON struct {
	Kind         string      `json:"kind"`
	ID           string      `json:"id"`
	Account      string      `json:"account"`
	Asset        string      `json:"asset"`
	Amount       *amountJSON `json:"amount"`
	Fee          *amountJSON `json:"fee"`
	Charged      *amountJSON `json:"charged"`
	SettlementID string      `json:"settlement_id"`
}

// flowRequestJSON 是对账输入：{"entries":[...]}。
type flowRequestJSON struct {
	Entries []flowEntryJSON `json:"entries"`
}

// FlowEntry 是校验通过后的一条流水。Index 是从 0 开始的输入位置。
type FlowEntry struct {
	Index        int
	Kind         string
	ID           string
	Account      string
	Asset        string
	Amount       int64
	Fee          int64
	Charged      int64
	SettlementID string // 仅退款有意义
}

// FieldDiff 是一个不同字段：账本值与流水值逐字并列。
type FieldDiff struct {
	Field  string `json:"field"`
	Ledger string `json:"ledger"`
	Flow   string `json:"flow"`
}

// ReconRecordRef 指向一条账本成功记录，并携带其关联记录（付款被退时的退款
// 编号、退款的原付款编号），使每个能定位到账本的结果都可追溯。
type ReconRecordRef struct {
	Kind         string `json:"kind"`
	ID           string `json:"id"`
	Account      string `json:"account"`
	Asset        string `json:"asset"`
	Amount       int64  `json:"amount"`
	Fee          int64  `json:"fee"`
	Charged      int64  `json:"charged"`
	Seq          int64  `json:"seq"`
	SettlementID string `json:"settlement_id,omitempty"` // 退款记录：原付款编号
	RefundID     string `json:"refund_id,omitempty"`     // 结算已被退款时：退款编号
	RefundSeq    int64  `json:"refund_seq,omitempty"`
}

// ReconResult 是一条输入流水的核对结果，顺序与输入一致。
type ReconResult struct {
	Index     int             `json:"index"`

content.content:
120		Index     int             `json:"index"`
121		Kind      string          `json:"kind"`
122		ID        string          `json:"id"`
123		Status    string          `json:"status"`
124		Positions []int           `json:"positions,omitempty"` // duplicate：整组全部输入位置
125		Diffs     []FieldDiff     `json:"diffs,omitempty"`
126		Record    *ReconRecordRef `json:"record,omitempty"` // 命中账本记录时带上，可追溯关联结算/退款
127	}
128	
129	// ReconTotalRow 是一个 (账户, 资产) 组合单侧的金额汇总。金额使用十进制整数
130	// 字符串，累计可超过 int64 仍保持精确；不同资产各自一行，不相加、不抵消。
131	type ReconTotalRow struct {
132		Account       string `json:"account"`
133		Asset         string `json:"asset"`
134		ChargedTotal  string `json:"charged_total"`
135		RefundedTotal string `json:"refunded_total"`
136		NetCharged    string `json:"net_charged"`
137	}
138	
139	// ReconNetDiff 是一个组合的净扣款差额，方向为流水减账本。
140	type ReconNetDiff struct {
141		Account          string `json:"account"`
142		Asset            string `json:"asset"`
143		LedgerNetCharged string `json:"ledger_net_charged"`
144		FlowNetCharged   string `json:"flow_net_charged"`
145		NetChargedDiff   string `json:"net_charged_diff"`
146	}
147	
148	// ReconTotals 是账本侧与流水侧各自的汇总。
149	type ReconTotals struct {
150		Ledger []ReconTotalRow `json:"ledger"`
151		Flow   []ReconTotalRow `json:"flow"`
152	}
153	
154	// ReconReport 是一次对账的完整报告。
155	type ReconReport struct {
156		Results         []ReconResult    `json:"results"`
157		MissingPayments []ReconRecordRef `json:"missing_payments"`
158		MissingRefunds  []ReconRecordRef `json:"missing_refunds"`
159		Totals          ReconTotals      `json:"totals"`
160		NetDiff         []ReconNetDiff   `json:"net_diff"`
161		MaxPaymentSeq   int64            `json:"max_payment_seq"`
162		MaxRefundSeq    int64            `json:"max_refund_seq"`
163		PaymentAfter    int64            `json:"payment_after"`
164		PaymentThrough  int64            `json:"payment_through"`
165		RefundAfter     int64            `json:"refund_after"`
166		RefundThrough   int64            `json:"refund_through"`
167	}
168	
169	// ReconcileBounds 限定付款与退款各自的核对范围：每类记录只核对成功序号
170	// 满足 after < seq <= through 的记录（下界排除、上界包含）。两类记录各用
171	// 自己的序号，分别选择范围，不根据退款引用的付款序号判断退款是否入选。
172	//
173	// 指针为 nil 表示该侧不限制：下界缺省取 0，上界缺省取本次所见该类记录的
174	// 最大成功序号（即完整历史）。显式给出的上下界必须是非负 int64，且
175	// after <= through、through 不超过对应类别的最大成功序号；after == through
176	// 表示范围为空（该类记录全部不参加核对）。
177	type ReconcileBounds struct {
178		PaymentAfter   *int64
179		PaymentThrough *int64
180		RefundAfter    *int64
181		RefundThrough  *int64
182	}
183	
184	// validateFlowEntry 校验一条流水的语义约束（JSON 解析与 Go 直接调用共用，
185	// 保证两种提交方式对相同内容给出一致判断）：kind 只能是 payment/refund；
186	// 编号、账户、资产不能为空；amount、charged 必须为正，fee 必须非负；
187	// refund 还必须带非空 settlement_id。i 是该条目在传入列表中的位置。
188	//
189	// 注意这里只校验输入本身：amount+fee 是否等于 charged、退款引用的原付款
190	// 是否与账本一致属于核对结论（field_mismatch），不是参数错误。
191	func validateFlowEntry(i int, e FlowEntry) error {
192		at := func(msg string) error {
193			return ledgerError(ErrInvalid, "reconcile entry %d: %s", i, msg)
194		}
195		if e.Kind != "payment" && e.Kind != "refund" {
196			return at(fmt.Sprintf("unknown kind %q (want payment or refund)", e.Kind))
197		}
198		if e.ID == "" {
199			return at("id must not be empty")
200		}
201		if e.Account == "" {
202			return at("account must not be empty")
203		}
204		if e.Asset == "" {
205			return at("asset must not be empty")
206		}
207		if e.Amount <= 0 {
208			return at("amount must be a positive int64")
209		}
210		if e.Fee < 0 {
211			return at("fee must be a non-negative int64")
212		}
213		if e.Charged <= 0 {
214			return at("charged must be a positive int64")
215		}
216		if e.Kind == "refund" && e.SettlementID == "" {
217			return at("settlement_id must not be empty for a refund")
218		}
219		return nil
220	}
221	
222	// ParseReconcileRequest 严格解析对账输入。
223	// 字段缺失、类型不符、未知 kind、数值越界或非法 JSON 均返回 invalid_parameter；
224	// 任一条目不合法则整次拒绝，不产生部分结果。
225	func ParseReconcileRequest(raw []byte) ([]FlowEntry, error) {
226		dec := json.NewDecoder(bytes.NewReader(raw))
227		var req flowRequestJSON
228		if err := dec.Decode(&req); err != nil {
229			return nil, ledgerError(ErrInvalid, "parse reconcile JSON: %v", err)
230		}
231		if tok, err := dec.Token(); err != io.EOF {
232			if err == nil {
233				return nil, ledgerError(ErrInvalid, "reconcile: unexpected trailing content after JSON document (token %v)", tok)
234			}
235			return nil, ledgerError(ErrInvalid, "reconcile: %v", err)
236		}
237		// entries 必须显式提供；{} 等缺省列表的文档视为非法输入，
238		// 只有 {"entries":[]} 才表示“空列表：全部账本记录缺失”。
239		if req.Entries == nil {
240			return nil, ledgerError(ErrInvalid, "reconcile: entries is required")
241		}
242	
243		entries := make([]FlowEntry, 0, len(req.Entries))
244		for i, e := range req.Entries {
245			// 结构性约束（字段必须提供且为 int64）只存在于 JSON 入口。
246			if e.Amount == nil {
247				return nil, ledgerError(ErrInvalid, "reconcile entry %d: amount is required and must be an int64 integer", i)
248			}
249			if e.Fee == nil {
250				return nil, ledgerError(ErrInvalid, "reconcile entry %d: fee is required and must be an int64 integer", i)
251			}
252			if e.Charged == nil {
253				return nil, ledgerError(ErrInvalid, "reconcile entry %d: charged is required and must be an int64 integer", i)
254			}
255			entry := FlowEntry{
256				Index:        i,
257				Kind:         e.Kind,
258				ID:           e.ID,
259				Account:      e.Account,
260				Asset:        e.Asset,
261				Amount:       e.Amount.v,
262				Fee:          e.Fee.v,
263				Charged:      e.Charged.v,
264				SettlementID: e.SettlementID,
265			}
266			// 语义约束与 Go 入口共用同一套校验，报错信息也保持一致。
267			if err := validateFlowEntry(i, entry); err != nil {
268				return nil, err
269			}
270			entries = append(entries, entry)
271		}
272		return entries, nil
273	}
274	
275	// reconSide 累计单侧（账本或流水）的金额。流水侧可能包含账本外的组合，
276	// 且累计允许超过 int64，因此一律用大整数。
277	type reconSide struct {
278		charged  map[balanceKey]*big.Int
279		refunded map[balanceKey]*big.Int
280	}
281	
282	func newReconSide() reconSide {
283		return reconSide{charged: map[balanceKey]*big.Int{}, refunded: map[balanceKey]*big.Int{}}
284	}
285	
286	func (s *reconSide) addCharged(k balanceKey, v int64) {
287		x := s.charged[k]
288		if x == nil {
289			x = new(big.Int)
290			s.charged[k] = x
291		}
292		x.Add(x, big.NewInt(v))
293	}
294	
295	func (s *reconSide) addRefund(k balanceKey, v int64) {
296		x := s.refunded[k]
297		if x == nil {
298			x = new(big.Int)
299			s.refunded[k] = x
300		}
301		x.Add(x, big.NewInt(v))
302	}
303	
304	// ReconcileFlow 对一批外部流水与当前账本状态做只读对账，核对范围为完整
305	// 历史（付款与退款都取各自全部成功记录）。等价于 ReconcileFlowRanged 传入
306	// 空边界。
307	//
308	// entries 与命令行 {"entries":[...]} 适用同一套输入检查：kind 只能是
309	// payment/refund，编号/账户/资产非空，amount、charged 为正，fee 非负，
310	// refund 必须带 settlement_id。任一条目不合法即返回 invalid_parameter
311	// （报告为 nil，不产生部分结果），Go 调用者无需先把条目转成 JSON 解析。
312	// nil 或空列表表示没有外部流水，正常列出核对范围内的账本缺失记录。
313	func (l *Ledger) ReconcileFlow(entries []FlowEntry) (*ReconReport, error) {
314		return l.ReconcileFlowRanged(entries, ReconcileBounds{})
315	}
316	
317	// resolveReconRange 确定一类记录的实际核对边界 (after, through]，并校验：
318	// 边界必须非负、after 不大于 through、through 不超过该类最大成功序号。
319	// 空历史的最大序号为零，因此缺省边界为 (0,0]，范围为空。
320	func resolveReconRange(kind string, after, through *int64, maxSeq int64) (int64, int64, error) {
321		a := int64(0)
322		if after != nil {
323			a = *after
324		}
325		t := maxSeq
326		if through != nil {
327			t = *through
328		}
329		if a < 0 {
330			return 0, 0, ledgerError(ErrInvalid, "reconcile %s bounds: after must be a non-negative int64, got %d", kind, a)
331		}
332		if t < 0 {
333			return 0, 0, ledgerError(ErrInvalid, "reconcile %s bounds: through must be a non-negative int64, got %d", kind, t)
334		}
335		if a > t {
336			return 0, 0, ledgerError(ErrInvalid, "reconcile %s bounds: after %d must not exceed through %d", kind, a, t)
337		}
338		if t > maxSeq {
339			return 0, 0, ledgerError(ErrInvalid, "reconcile %s bounds: through %d exceeds max seq %d", kind, t, maxSeq)
340		}
341		return a, t, nil
342	}
343	
344	// ReconcileFlowRanged 对一批外部流水与当前账本状态做只读对账，只核对成功
345	// 序号落在边界内的记录（after < seq <= through）。边界不改变账本状态，
346	// 整份报告仍在同一把账本互斥锁内生成，对应同一个完整账本状态。
347	//
348	// 范围只影响记录是否参加核对，不切断关联：入选退款仍可指向范围外付款，
349	// 入选付款仍携带范围外退款的信息。命中同类型同编号但记录在范围外的流水
350	// 返回 out_of_scope（携带账本记录、不比较字段、不计入流水侧汇总）；该编号
351	// 在流水中出现多次时全部按 out_of_scope 处理。
352	func (l *Ledger) ReconcileFlowRanged(entries []FlowEntry, bounds ReconcileBounds) (*ReconReport, error) {
353		if err := l.beginOp(); err != nil {
354			return nil, err
355		}
356		defer l.endOp()
357	
358		// 与命令行入口相同的输入检查：按传入列表顺序找到第一条非法流水即整次
359		// 拒绝（invalid_parameter），报告为空、不产生部分汇总，也不触碰账本。
360		// 位置用列表下标而非调用者给出的 Index；校验只读、不改写传入条目。
361		for i := range entries {
362			if err := validateFlowEntry(i, entries[i]); err != nil {
363				return nil, err
364			}
365		}
366	
367		l.reg.mu.Lock()
368		defer l.reg.mu.Unlock()
369	
370		st := l.stateView()
371	
372		maxPay := int64(len(st.Settlements))
373		maxRef := int64(len(st.Refunds))
374		payAfter, payThrough, err := resolveReconRange("payment", bounds.PaymentAfter, bounds.PaymentThrough, maxPay)
375		if err != nil {
376			return nil, err
377		}
378		refAfter, refThrough, err := resolveReconRange("refund", bounds.RefundAfter, bounds.RefundThrough, maxRef)
379		if err != nil {
380			return nil, err
381		}
382		inPayRange := func(seq int64) bool { return seq > payAfter && seq <= payThrough }
383		inRefRange := func(seq int64) bool { return seq > refAfter && seq <= refThrough }
384	
385		// 结算编号 / 退款编号各自索引：同名编号也不会混为一笔。
386		// 关联索引始终基于完整历史：范围不切断付款与退款之间的关联。
387		payByID := make(map[string]*Record, len(st.Settlements))
388		for i := range st.Settlements {
389			payByID[st.Settlements[i].ID] = &st.Settlements[i]
390		}
391		refundByID := make(map[string]*RefundRecord, len(st.Refunds))
392		refundOfPay := make(map[string]*RefundRecord, len(st.Refunds))
393		for i := range st.Refunds {
394			r := &st.Refunds[i]
395			refundByID[r.ID] = r
396			refundOfPay[r.SettlementID] = r
397		}
398	
399		// 统计每个 (kind,id) 在输入中出现的全部位置：出现多次则整组重复，
400		// 无论内容是否相同。
401		type idUse struct{ positions []int }
402		paySeen := map[string]*idUse{}
403		refundSeen := map[string]*idUse{}
404		for i := range entries {
405			e := &entries[i]
406			m := paySeen
407			if e.Kind == "refund" {
408				m = refundSeen
409			}
410			u := m[e.ID]
411			if u == nil {
412				u = &idUse{}
413				m[e.ID] = u
414			}
415			u.positions = append(u.positions, e.Index)
416		}
417	
418		report := &ReconReport{
419			Results:         make([]ReconResult, 0, len(entries)),
420			MissingPayments: []ReconRecordRef{},
421			MissingRefunds:  []ReconRecordRef{},
422			NetDiff:         []ReconNetDiff{},
423			MaxPaymentSeq:   maxPay,
424			MaxRefundSeq:    maxRef,
425			PaymentAfter:    payAfter,
426			PaymentThrough:  payThrough,
427			RefundAfter:     refAfter,
428			RefundThrough:   refThrough,
429		}
430	
431		ledgerSide := newReconSide()
432		flowSide := newReconSide()
433		coveredPay := map[string]bool{} // 唯一且命中账本入选记录的付款编号（含字段不符）
434		coveredRefund := map[string]bool{}
435	
436		// 逐条结果（保持输入顺序）。
437		for i := range entries {
438			e := &entries[i]
439			res := ReconResult{Index: e.Index, Kind: e.Kind, ID: e.ID}
440			k := balanceKey{e.Account, e.Asset}
441	
442			uses := paySeen[e.ID]
443			var payRec *Record
444			var refRec *RefundRecord
445			inRange := false
446			if e.Kind == "payment" {
447				payRec = payByID[e.ID]
448				inRange = payRec != nil && inPayRange(payRec.Seq)
449			} else {
450				uses = refundSeen[e.ID]
451				refRec = refundByID[e.ID]
452				inRange = refRec != nil && inRefRange(refRec.Seq)
453			}
454	
455			// 1. 命中同类型同编号但记录在范围外：不比较字段、不计入流水侧汇总；
456			//    该编号在流水中出现多次时全部按 out_of_scope 处理（优先于整组重复）。
457			if (payRec != nil || refRec != nil) && !inRange {
458				res.Status = ReconOutOfScope
459				if e.Kind == "payment" {
460					ref := paymentRef(payRec, refundOfPay[e.ID])
461					res.Record = &ref
462				} else {
463					ref := refundRef(refRec)
464					res.Record = &ref
465				}
466				report.Results = append(report.Results, res)
467				continue
468			}
469	
470			// 2. 记录在范围内或账本无此编号：保留整组重复判定，流水侧合计仍包含
471			//    每一条（范围内重复项与账本外流水逐条计入）。
472			if len(uses.positions) > 1 {
473				res.Status = ReconDuplicate
474				res.Positions = append([]int(nil), uses.positions...)
475				if e.Kind == "payment" {
476					flowSide.addCharged(k, e.Charged)
477					if payRec != nil {
478						ref := paymentRef(payRec, refundOfPay[e.ID])
479						res.Record = &ref
480					}
481				} else {
482					flowSide.addRefund(k, e.Charged)
483					if refRec != nil {
484						ref := refundRef(refRec)
485						res.Record = &ref
486					}
487				}
488				report.Results = append(report.Results, res)
489				continue
490			}
491	
492			// 3. 唯一条目：命中入选记录则逐字段核对，否则账本缺这笔。
493			if e.Kind == "payment" {
494				flowSide.addCharged(k, e.Charged)
495				if payRec != nil {
496					coveredPay[e.ID] = true
497					ref := paymentRef(payRec, refundOfPay[e.ID])
498					res.Record = &ref
499					if diffs := comparePayment(payRec, e); len(diffs) > 0 {
500						res.Status = ReconFieldMismatch
501						res.Diffs = diffs
502					} else {
503						res.Status = ReconMatched
504					}
505				} else {
506					res.Status = ReconMissingInLedger
507				}
508			} else {
509				flowSide.addRefund(k, e.Charged)
510				if refRec != nil {
511					coveredRefund[e.ID] = true
512					ref := refundRef(refRec)
513					res.Record = &ref
514					if diffs := compareRefund(refRec, e); len(diffs) > 0 {
515						res.Status = ReconFieldMismatch
516						res.Diffs = diffs
517					} else {
518						res.Status = ReconMatched
519					}
520				} else {
521					res.Status = ReconMissingInLedger
522				}
523			}
524			report.Results = append(report.Results, res)
525		}
526	
527		// 账本侧合计只包含入选记录：已退款的付款仍按原扣款计入，退款单独计入
528		// 退款侧；只选退款时扣款合计为零，不会顺带计入原付款。
529		for i := range st.Settlements {
530			r := &st.Settlements[i]
531			if inPayRange(r.Seq) {
532				ledgerSide.addCharged(balanceKey{r.Account, r.Asset}, r.Charged)
533			}
534		}
535		for i := range st.Refunds {
536			r := &st.Refunds[i]
537			if inRefRange(r.Seq) {
538				ledgerSide.addRefund(balanceKey{r.Account, r.Asset}, r.Charged)
539			}
540		}
541	
542		// 入选但流水未覆盖的成功记录另列缺失（先付款后退款，各按成功顺序）。
543		// 唯一出现即算覆盖（含字段不符）；重复组对应记录按规则不列为缺失；
544		// 范围外记录不列入缺失。
545		for i := range st.Settlements {
546			r := &st.Settlements[i]
547			if !inPayRange(r.Seq) {
548				continue
549			}
550			if coveredPay[r.ID] {
551				continue
552			}
553			if u := paySeen[r.ID]; u != nil && len(u.positions) > 1 {
554				continue
555			}
556			report.MissingPayments = append(report.MissingPayments, paymentRef(r, refundOfPay[r.ID]))
557		}
558		for i := range st.Refunds {
559			r := &st.Refunds[i]
560			if !inRefRange(r.Seq) {
561				continue
562			}
563			if coveredRefund[r.ID] {
564				continue
565			}
566			if u := refundSeen[r.ID]; u != nil && len(u.positions) > 1 {
567				continue
568			}
569			report.MissingRefunds = append(report.MissingRefunds, refundRef(r))
570		}
571	
572		report.Totals = ReconTotals{
573			Ledger: buildTotalRows(ledgerSide),
574			Flow:   buildTotalRows(flowSide),
575		}
576		report.NetDiff = buildNetDiff(ledgerSide, flowSide)
577		return report, nil
578	}
579	
580	// comparePayment 比较付款的账户、资产、amount、fee、charged 五个字段。
581	func comparePayment(r *Record, e *FlowEntry) []FieldDiff {
582		var diffs []FieldDiff
583		addStr := func(field, ledger, flow string) {
584			if ledger != flow {
585				diffs = append(diffs, FieldDiff{Field: field, Ledger: ledger, Flow: flow})
586			}
587		}
588		addInt := func(field string, ledger, flow int64) {
589			if ledger != flow {
590				diffs = append(diffs, FieldDiff{Field: field, Ledger: fmt.Sprintf("%d", ledger), Flow: fmt.Sprintf("%d", flow)})
591			}
592		}
593		addStr("account", r.Account, e.Account)
594		addStr("asset", r.Asset, e.Asset)
595		addInt("amount", r.Amount, e.Amount)
596		addInt("fee", r.Fee, e.Fee)
597		addInt("charged", r.Charged, e.Charged)
598		return diffs
599	}
600	
601	// compareRefund 比较退款的账户、资产、三个金额及原付款编号。
602	func compareRefund(r *RefundRecord, e *FlowEntry) []FieldDiff {
603		var diffs []FieldDiff
604		addStr := func(field, ledger, flow string) {
605			if ledger != flow {
606				diffs = append(diffs, FieldDiff{Field: field, Ledger: ledger, Flow: flow})
607			}
608		}
609		addInt := func(field string, ledger, flow int64) {
610			if ledger != flow {
611				diffs = append(diffs, FieldDiff{Field: field, Ledger: fmt.Sprintf("%d", ledger), Flow: fmt.Sprintf("%d", flow)})
612			}
613		}
614		addStr("account", r.Account, e.Account)
615		addStr("asset", r.Asset, e.Asset)
616		addInt("amount", r.Amount, e.Amount)
617		addInt("fee", r.Fee, e.Fee)
618		addInt("charged", r.Charged, e.Charged)
619		addStr("settlement_id", r.SettlementID, e.SettlementID)
620		return diffs
621	}
622	
623	func paymentRef(r *Record, rf *RefundRecord) ReconRecordRef {
624		ref := ReconRecordRef{
625			Kind:    "payment",
626			ID:      r.ID,
627			Account: r.Account,
628			Asset:   r.Asset,
629			Amount:  r.Amount,
630			Fee:     r.Fee,
631			Charged: r.Charged,
632			Seq:     r.Seq,
633		}
634		if rf != nil {
635			ref.RefundID = rf.ID
636			ref.RefundSeq = rf.Seq
637		}
638		return ref
639	}
640	
641	func refundRef(r *RefundRecord) ReconRecordRef {
642		return ReconRecordRef{
643			Kind:         "refund",
644			ID:           r.ID,
645			Account:      r.Account,
646			Asset:        r.Asset,
647			Amount:       r.Amount,
648			Fee:          r.Fee,
649			Charged:      r.Charged,
650			Seq:          r.Seq,
651			SettlementID: r.SettlementID,
652		}
653	}
654	
655	// sideNet 返回某组合的净扣款（扣款 - 退款）。
656	func sideNet(side reconSide, k balanceKey) *big.Int {
657		charged := new(big.Int)
658		if x := side.charged[k]; x != nil {
659			charged.Set(x)
660		}
661		refunded := new(big.Int)
662		if x := side.refunded[k]; x != nil {
663			refunded.Set(x)
664		}
665		return charged.Sub(charged, refunded)
666	}
667	
668	func allKeys(a, b reconSide) []balanceKey {
669		seen := map[balanceKey]bool{}
670		var keys []balanceKey
671		add := func(m map[balanceKey]*big.Int) {
672			for k := range m {
673				if !seen[k] {
674					seen[k] = true
675					keys = append(keys, k)
676				}
677			}
678		}
679		add(a.charged)
680		add(a.refunded)
681		add(b.charged)
682		add(b.refunded)
683		sort.Slice(keys, func(i, j int) bool {
684			if keys[i].account != keys[j].account {
685				return keys[i].account < keys[j].account
686			}
687			return keys[i].asset < keys[j].asset
688		})
689		return keys
690	}
691	
692	// buildTotalRows 按账户、资产排序输出单侧汇总；净扣款 = 扣款 - 退款。
693	func buildTotalRows(side reconSide) []ReconTotalRow {
694		keys := allKeys(side, reconSide{})
695		out := make([]ReconTotalRow, 0, len(keys))
696		for _, k := range keys {
697			charged := new(big.Int)
698			if x := side.charged[k]; x != nil {
699				charged.Set(x)
700			}
701			refunded := new(big.Int)
702			if x := side.refunded[k]; x != nil {
703				refunded.Set(x)
704			}
705			net := new(big.Int).Sub(new(big.Int).Set(charged), refunded)
706			out = append(out, ReconTotalRow{
707				Account:       k.account,
708				Asset:         k.asset,
709				ChargedTotal:  charged.String(),
710				RefundedTotal: refunded.String(),
711				NetCharged:    net.String(),
712			})
713		}
714		return out
715	}
716	
717	// buildNetDiff 输出每个（任一侧出现过的）组合的净扣款差额，方向为流水减账本。
718	func buildNetDiff(ledger, flow reconSide) []ReconNetDiff {
719		out := make([]ReconNetDiff, 0)
720		for _, k := range allKeys(ledger, flow) {
721			lNet := sideNet(ledger, k)
722			fNet := sideNet(flow, k)
723			diff := new(big.Int).Sub(new(big.Int).Set(fNet), lNet)
724			out = append(out, ReconNetDiff{
725				Account:          k.account,
726				Asset:            k.asset,
727				LedgerNetCharged: lNet.String(),
728				FlowNetCharged:   fNet.String(),
729				NetChargedDiff:   diff.String(),
730			})
731		}
732		return out
733	}
734

file.content:
	Index     int             `json:"index"`
	Kind      string          `json:"kind"`
	ID        string          `json:"id"`
	Status    string          `json:"status"`
	Positions []int           `json:"positions,omitempty"` // duplicate：整组全部输入位置
	Diffs     []FieldDiff     `json:"diffs,omitempty"`
	Record    *ReconRecordRef `json:"record,omitempty"` // 命中账本记录时带上，可追溯关联结算/退款
}

// ReconTotalRow 是一个 (账户, 资产) 组合单侧的金额汇总。金额使用十进制整数
// 字符串，累计可超过 int64 仍保持精确；不同资产各自一行，不相加、不抵消。
type ReconTotalRow struct {
	Account       string `json:"account"`
	Asset         string `json:"asset"`
	ChargedTotal  string `json:"charged_total"`
	RefundedTotal string `json:"refunded_total"`
	NetCharged    string `json:"net_charged"`
}

// ReconNetDiff 是一个组合的净扣款差额，方向为流水减账本。
type ReconNetDiff struct {
	Account          string `json:"account"`
	Asset            string `json:"asset"`
	LedgerNetCharged string `json:"ledger_net_charged"`
	FlowNetCharged   string `json:"flow_net_charged"`
	NetChargedDiff   string `json:"net_charged_diff"`
}

// ReconTotals 是账本侧与流水侧各自的汇总。
type ReconTotals struct {
	Ledger []ReconTotalRow `json:"ledger"`
	Flow   []ReconTotalRow `json:"flow"`
}

// ReconReport 是一次对账的完整报告。
type ReconReport struct {
	Results         []ReconResult    `json:"results"`
	MissingPayments []ReconRecordRef `json:"missing_payments"`
	MissingRefunds  []ReconRecordRef `json:"missing_refunds"`
	Totals          ReconTotals      `json:"totals"`
	NetDiff         []ReconNetDiff   `json:"net_diff"`
	MaxPaymentSeq   int64            `json:"max_payment_seq"`
	MaxRefundSeq    int64            `json:"max_refund_seq"`
	PaymentAfter    int64            `json:"payment_after"`
	PaymentThrough  int64            `json:"payment_through"`
	RefundAfter     int64            `json:"refund_after"`
	RefundThrough   int64            `json:"refund_through"`
}

// ReconcileBounds 限定付款与退款各自的核对范围：每类记录只核对成功序号
// 满足 after < seq <= through 的记录（下界排除、上界包含）。两类记录各用
// 自己的序号，分别选择范围，不根据退款引用的付款序号判断退款是否入选。
//
// 指针为 nil 表示该侧不限制：下界缺省取 0，上界缺省取本次所见该类记录的
// 最大成功序号（即完整历史）。显式给出的上下界必须是非负 int64，且
// after <= through、through 不超过对应类别的最大成功序号；after == through
// 表示范围为空（该类记录全部不参加核对）。
type ReconcileBounds struct {
	PaymentAfter   *int64
	PaymentThrough *int64
	RefundAfter    *int64
	RefundThrough  *int64
}

// validateFlowEntry 校验一条流水的语义约束（JSON 解析与 Go 直接调用共用，
// 保证两种提交方式对相同内容给出一致判断）：kind 只能是 payment/refund；
// 编号、账户、资产不能为空；amount、charged 必须为正，fee 必须非负；
// refund 还必须带非空 settlement_id。i 是该条目在传入列表中的位置。
//
// 注意这里只校验输入本身：amount+fee 是否等于 charged、退款引用的原付款
// 是否与账本一致属于核对结论（field_mismatch），不是参数错误。
func validateFlowEntry(i int, e FlowEntry) error {
	at := func(msg string) error {
		return ledgerError(ErrInvalid, "reconcile entry %d: %s", i, msg)
	}
	if e.Kind != "payment" && e.Kind != "refund" {
		return at(fmt.Sprintf("unknown kind %q (want payment or refund)", e.Kind))
	}
	if e.ID == "" {
		return at("id must not be empty")
	}
	if e.Account == "" {
		return at("account must not be empty")
	}
	if e.Asset == "" {
		return at("asset must not be empty")
	}
	if e.Amount <= 0 {
		return at("amount must be a positive int64")
	}
	if e.Fee < 0 {
		return at("fee must be a non-negative int64")
	}
	if e.Charged <= 0 {
		return at("charged must be a positive int64")
	}
	if e.Kind == "refund" && e.SettlementID == "" {
		return at("settlement_id must not be empty for a refund")
	}
	return nil
}

// ParseReconcileRequest 严格解析对账输入。
// 字段缺失、类型不符、未知 kind、数值越界或非法 JSON 均返回 invalid_parameter；
// 任一条目不合法则整次拒绝，不产生部分结果。
func ParseReconcileRequest(raw []byte) ([]FlowEntry, error) {
	dec := json.NewDecoder(bytes.NewReader(raw))
	var req flowRequestJSON
	if err := dec.Decode(&req); err != nil {
		return nil, ledgerError(ErrInvalid, "parse reconcile JSON: %v", err)
	}
	if tok, err := dec.Token(); err != io.EOF {
		if err == nil {
			return nil, ledgerError(ErrInvalid, "reconcile: unexpected trailing content after JSON document (token %v)", tok)
		}
		return nil, ledgerError(ErrInvalid, "reconcile: %v", err)
	}
	// entries 必须显式提供；{} 等缺省列表的文档视为非法输入，
	// 只有 {"entries":[]} 才表示“空列表：全部账本记录缺失”。
	if req.Entries == nil {
		return nil, ledgerError(ErrInvalid, "reconcile: entries is required")
	}

	entries := make([]FlowEntry, 0, len(req.Entries))
	for i, e := range req.Entries {
		// 结构性约束（字段必须提供且为 int64）只存在于 JSON 入口。
		if e.Amount == nil {
			return nil, ledgerError(ErrInvalid, "reconcile entry %d: amount is required and must be an int64 integer", i)
		}
		if e.Fee == nil {
			return nil, ledgerError(ErrInvalid, "reconcile entry %d: fee is required and must be an int64 integer", i)
		}
		if e.Charged == nil {
			return nil, ledgerError(ErrInvalid, "reconcile entry %d: charged is required and must be an int64 integer", i)
		}
		entry := FlowEntry{
			Index:        i,
			Kind:         e.Kind,
			ID:           e.ID,
			Account:      e.Account,
			Asset:        e.Asset,
			Amount:       e.Amount.v,
			Fee:          e.Fee.v,
			Charged:      e.Charged.v,
			SettlementID: e.SettlementID,
		}
		// 语义约束与 Go 入口共用同一套校验，报错信息也保持一致。
		if err := validateFlowEntry(i, entry); err != nil {
			return nil, err
		}
		entries = append(entries, entry)
	}
	return entries, nil
}

// reconSide 累计单侧（账本或流水）的金额。流水侧可能包含账本外的组合，
// 且累计允许超过 int64，因此一律用大整数。
type reconSide struct {
	charged  map[balanceKey]*big.Int
	refunded map[balanceKey]*big.Int
}

func newReconSide() reconSide {
	return reconSide{charged: map[balanceKey]*big.Int{}, refunded: map[balanceKey]*big.Int{}}
}

func (s *reconSide) addCharged(k balanceKey, v int64) {
	x := s.charged[k]
	if x == nil {
		x = new(big.Int)
		s.charged[k] = x
	}
	x.Add(x, big.NewInt(v))
}

func (s *reconSide) addRefund(k balanceKey, v int64) {
	x := s.refunded[k]
	if x == nil {
		x = new(big.Int)
		s.refunded[k] = x
	}
	x.Add(x, big.NewInt(v))
}

// ReconcileFlow 对一批外部流水与当前账本状态做只读对账，核对范围为完整
// 历史（付款与退款都取各自全部成功记录）。等价于 ReconcileFlowRanged 传入
// 空边界。
//
// entries 与命令行 {"entries":[...]} 适用同一套输入检查：kind 只能是
// payment/refund，编号/账户/资产非空，amount、charged 为正，fee 非负，
// refund 必须带 settlement_id。任一条目不合法即返回 invalid_parameter
// （报告为 nil，不产生部分结果），Go 调用者无需先把条目转成 JSON 解析。
// nil 或空列表表示没有外部流水，正常列出核对范围内的账本缺失记录。
func (l *Ledger) ReconcileFlow(entries []FlowEntry) (*ReconReport, error) {
	return l.ReconcileFlowRanged(entries, ReconcileBounds{})
}

// resolveReconRange 确定一类记录的实际核对边界 (after, through]，并校验：
// 边界必须非负、after 不大于 through、through 不超过该类最大成功序号。
// 空历史的最大序号为零，因此缺省边界为 (0,0]，范围为空。
func resolveReconRange(kind string, after, through *int64, maxSeq int64) (int64, int64, error) {
	a := int64(0)
	if after != nil {
		a = *after
	}
	t := maxSeq
	if through != nil {
		t = *through
	}
	if a < 0 {
		return 0, 0, ledgerError(ErrInvalid, "reconcile %s bounds: after must be a non-negative int64, got %d", kind, a)
	}
	if t < 0 {
		return 0, 0, ledgerError(ErrInvalid, "reconcile %s bounds: through must be a non-negative int64, got %d", kind, t)
	}
	if a > t {
		return 0, 0, ledgerError(ErrInvalid, "reconcile %s bounds: after %d must not exceed through %d", kind, a, t)
	}
	if t > maxSeq {
		return 0, 0, ledgerError(ErrInvalid, "reconcile %s bounds: through %d exceeds max seq %d", kind, t, maxSeq)
	}
	return a, t, nil
}

// ReconcileFlowRanged 对一批外部流水与当前账本状态做只读对账，只核对成功
// 序号落在边界内的记录（after < seq <= through）。边界不改变账本状态，
// 整份报告仍在同一把账本互斥锁内生成，对应同一个完整账本状态。
//
// 范围只影响记录是否参加核对，不切断关联：入选退款仍可指向范围外付款，
// 入选付款仍携带范围外退款的信息。命中同类型同编号但记录在范围外的流水
// 返回 out_of_scope（携带账本记录、不比较字段、不计入流水侧汇总）；该编号
// 在流水中出现多次时全部按 out_of_scope 处理。
func (l *Ledger) ReconcileFlowRanged(entries []FlowEntry, bounds ReconcileBounds) (*ReconReport, error) {
	if err := l.beginOp(); err != nil {
		return nil, err
	}
	defer l.endOp()

	// 与命令行入口相同的输入检查：按传入列表顺序找到第一条非法流水即整次
	// 拒绝（invalid_parameter），报告为空、不产生部分汇总，也不触碰账本。
	// 位置用列表下标而非调用者给出的 Index；校验只读、不改写传入条目。
	for i := range entries {
		if err := validateFlowEntry(i, entries[i]); err != nil {
			return nil, err
		}
	}

	l.reg.mu.Lock()
	defer l.reg.mu.Unlock()

	st := l.stateView()

	maxPay := int64(len(st.Settlements))
	maxRef := int64(len(st.Refunds))
	payAfter, payThrough, err := resolveReconRange("payment", bounds.PaymentAfter, bounds.PaymentThrough, maxPay)
	if err != nil {
		return nil, err
	}
	refAfter, refThrough, err := resolveReconRange("refund", bounds.RefundAfter, bounds.RefundThrough, maxRef)
	if err != nil {
		return nil, err
	}
	inPayRange := func(seq int64) bool { return seq > payAfter && seq <= payThrough }
	inRefRange := func(seq int64) bool { return seq > refAfter && seq <= refThrough }

	// 结算编号 / 退款编号各自索引：同名编号也不会混为一笔。
	// 关联索引始终基于完整历史：范围不切断付款与退款之间的关联。
	payByID := make(map[string]*Record, len(st.Settlements))
	for i := range st.Settlements {
		payByID[st.Settlements[i].ID] = &st.Settlements[i]
	}
	refundByID := make(map[string]*RefundRecord, len(st.Refunds))
	refundOfPay := make(map[string]*RefundRecord, len(st.Refunds))
	for i := range st.Refunds {
		r := &st.Refunds[i]
		refundByID[r.ID] = r
		refundOfPay[r.SettlementID] = r
	}

	// 统计每个 (kind,id) 在输入中出现的全部位置：出现多次则整组重复，
	// 无论内容是否相同。
	type idUse struct{ positions []int }
	paySeen := map[string]*idUse{}
	refundSeen := map[string]*idUse{}
	for i := range entries {
		e := &entries[i]
		m := paySeen
		if e.Kind == "refund" {
			m = refundSeen
		}
		u := m[e.ID]
		if u == nil {
			u = &idUse{}
			m[e.ID] = u
		}
		u.positions = append(u.positions, e.Index)
	}

	report := &ReconReport{
		Results:         make([]ReconResult, 0, len(entries)),
		MissingPayments: []ReconRecordRef{},
		MissingRefunds:  []ReconRecordRef{},
		NetDiff:         []ReconNetDiff{},
		MaxPaymentSeq:   maxPay,
		MaxRefundSeq:    maxRef,
		PaymentAfter:    payAfter,
		PaymentThrough:  payThrough,
		RefundAfter:     refAfter,
		RefundThrough:   refThrough,
	}

	ledgerSide := newReconSide()
	flowSide := newReconSide()
	coveredPay := map[string]bool{} // 唯一且命中账本入选记录的付款编号（含字段不符）
	coveredRefund := map[string]bool{}

	// 逐条结果（保持输入顺序）。
	for i := range entries {
		e := &entries[i]
		res := ReconResult{Index: e.Index, Kind: e.Kind, ID: e.ID}
		k := balanceKey{e.Account, e.Asset}

		uses := paySeen[e.ID]
		var payRec *Record
		var refRec *RefundRecord
		inRange := false
		if e.Kind == "payment" {
			payRec = payByID[e.ID]
			inRange = payRec != nil && inPayRange(payRec.Seq)
		} else {
			uses = refundSeen[e.ID]
			refRec = refundByID[e.ID]
			inRange = refRec != nil && inRefRange(refRec.Seq)
		}

		// 1. 命中同类型同编号但记录在范围外：不比较字段、不计入流水侧汇总；
		//    该编号在流水中出现多次时全部按 out_of_scope 处理（优先于整组重复）。
		if (payRec != nil || refRec != nil) && !inRange {
			res.Status = ReconOutOfScope
			if e.Kind == "payment" {
				ref := paymentRef(payRec, refundOfPay[e.ID])
				res.Record = &ref
			} else {
				ref := refundRef(refRec)
				res.Record = &ref
			}
			report.Results = append(report.Results, res)
			continue
		}

		// 2. 记录在范围内或账本无此编号：保留整组重复判定，流水侧合计仍包含
		//    每一条（范围内重复项与账本外流水逐条计入）。
		if len(uses.positions) > 1 {
			res.Status = ReconDuplicate
			res.Positions = append([]int(nil), uses.positions...)
			if e.Kind == "payment" {
				flowSide.addCharged(k, e.Charged)
				if payRec != nil {
					ref := paymentRef(payRec, refundOfPay[e.ID])
					res.Record = &ref
				}
			} else {
				flowSide.addRefund(k, e.Charged)
				if refRec != nil {
					ref := refundRef(refRec)
					res.Record = &ref
				}
			}
			report.Results = append(report.Results, res)
			continue
		}

		// 3. 唯一条目：命中入选记录则逐字段核对，否则账本缺这笔。
		if e.Kind == "payment" {
			flowSide.addCharged(k, e.Charged)
			if payRec != nil {
				coveredPay[e.ID] = true
				ref := paymentRef(payRec, refundOfPay[e.ID])
				res.Record = &ref
				if diffs := comparePayment(payRec, e); len(diffs) > 0 {
					res.Status = ReconFieldMismatch
					res.Diffs = diffs
				} else {
					res.Status = ReconMatched
				}
			} else {
				res.Status = ReconMissingInLedger
			}
		} else {
			flowSide.addRefund(k, e.Charged)
			if refRec != nil {
				coveredRefund[e.ID] = true
				ref := refundRef(refRec)
				res.Record = &ref
				if diffs := compareRefund(refRec, e); len(diffs) > 0 {
					res.Status = ReconFieldMismatch
					res.Diffs = diffs
				} else {
					res.Status = ReconMatched
				}
			} else {
				res.Status = ReconMissingInLedger
			}
		}
		report.Results = append(report.Results, res)
	}

	// 账本侧合计只包含入选记录：已退款的付款仍按原扣款计入，退款单独计入
	// 退款侧；只选退款时扣款合计为零，不会顺带计入原付款。
	for i := range st.Settlements {
		r := &st.Settlements[i]
		if inPayRange(r.Seq) {
			ledgerSide.addCharged(balanceKey{r.Account, r.Asset}, r.Charged)
		}
	}
	for i := range st.Refunds {
		r := &st.Refunds[i]
		if inRefRange(r.Seq) {
			ledgerSide.addRefund(balanceKey{r.Account, r.Asset}, r.Charged)
		}
	}

	// 入选但流水未覆盖的成功记录另列缺失（先付款后退款，各按成功顺序）。
	// 唯一出现即算覆盖（含字段不符）；重复组对应记录按规则不列为缺失；
	// 范围外记录不列入缺失。
	for i := range st.Settlements {
		r := &st.Settlements[i]
		if !inPayRange(r.Seq) {
			continue
		}
		if coveredPay[r.ID] {
			continue
		}
		if u := paySeen[r.ID]; u != nil && len(u.positions) > 1 {
			continue
		}
		report.MissingPayments = append(report.MissingPayments, paymentRef(r, refundOfPay[r.ID]))
	}
	for i := range st.Refunds {
		r := &st.Refunds[i]
		if !inRefRange(r.Seq) {
			continue
		}
		if coveredRefund[r.ID] {
			continue
		}
		if u := refundSeen[r.ID]; u != nil && len(u.positions) > 1 {
			continue
		}
		report.MissingRefunds = append(report.MissingRefunds, refundRef(r))
	}

	report.Totals = ReconTotals{
		Ledger: buildTotalRows(ledgerSide),
		Flow:   buildTotalRows(flowSide),
	}
	report.NetDiff = buildNetDiff(ledgerSide, flowSide)
	return report, nil
}

// comparePayment 比较付款的账户、资产、amount、fee、charged 五个字段。
func comparePayment(r *Record, e *FlowEntry) []FieldDiff {
	var diffs []FieldDiff
	addStr := func(field, ledger, flow string) {
		if ledger != flow {
			diffs = append(diffs, FieldDiff{Field: field, Ledger: ledger, Flow: flow})
		}
	}
	addInt := func(field string, ledger, flow int64) {
		if ledger != flow {
			diffs = append(diffs, FieldDiff{Field: field, Ledger: fmt.Sprintf("%d", ledger), Flow: fmt.Sprintf("%d", flow)})
		}
	}
	addStr("account", r.Account, e.Account)
	addStr("asset", r.Asset, e.Asset)
	addInt("amount", r.Amount, e.Amount)
	addInt("fee", r.Fee, e.Fee)
	addInt("charged", r.Charged, e.Charged)
	return diffs
}

// compareRefund 比较退款的账户、资产、三个金额及原付款编号。
func compareRefund(r *RefundRecord, e *FlowEntry) []FieldDiff {
	var diffs []FieldDiff
	addStr := func(field, ledger, flow string) {
		if ledger != flow {
			diffs = append(diffs, FieldDiff{Field: field, Ledger: ledger, Flow: flow})
		}
	}
	addInt := func(field string, ledger, flow int64) {
		if ledger != flow {
			diffs = append(diffs, FieldDiff{Field: field, Ledger: fmt.Sprintf("%d", ledger), Flow: fmt.Sprintf("%d", flow)})
		}
	}
	addStr("account", r.Account, e.Account)
	addStr("asset", r.Asset, e.Asset)
	addInt("amount", r.Amount, e.Amount)
	addInt("fee", r.Fee, e.Fee)
	addInt("charged", r.Charged, e.Charged)
	addStr("settlement_id", r.SettlementID, e.SettlementID)
	return diffs
}

func paymentRef(r *Record, rf *RefundRecord) ReconRecordRef {
	ref := ReconRecordRef{
		Kind:    "payment",
		ID:      r.ID,
		Account: r.Account,
		Asset:   r.Asset,
		Amount:  r.Amount,
		Fee:     r.Fee,
		Charged: r.Charged,
		Seq:     r.Seq,
	}
	if rf != nil {
		ref.RefundID = rf.ID
		ref.RefundSeq = rf.Seq
	}
	return ref
}

func refundRef(r *RefundRecord) ReconRecordRef {
	return ReconRecordRef{
		Kind:         "refund",
		ID:           r.ID,
		Account:      r.Account,
		Asset:        r.Asset,
		Amount:       r.Amount,
		Fee:          r.Fee,
		Charged:      r.Charged,
		Seq:          r.Seq,
		SettlementID: r.SettlementID,
	}
}

// sideNet 返回某组合的净扣款（扣款 - 退款）。
func sideNet(side reconSide, k balanceKey) *big.Int {
	charged := new(big.Int)
	if x := side.charged[k]; x != nil {
		charged.Set(x)
	}
	refunded := new(big.Int)
	if x := side.refunded[k]; x != nil {
		refunded.Set(x)
	}
	return charged.Sub(charged, refunded)
}

func allKeys(a, b reconSide) []balanceKey {
	seen := map[balanceKey]bool{}
	var keys []balanceKey
	add := func(m map[balanceKey]*big.Int) {
		for k := range m {
			if !seen[k] {
				seen[k] = true
				keys = append(keys, k)
			}
		}
	}
	add(a.charged)
	add(a.refunded)
	add(b.charged)
	add(b.refunded)
	sort.Slice(keys, func(i, j int) bool {
		if keys[i].account != keys[j].account {
			return keys[i].account < keys[j].account
		}
		return keys[i].asset < keys[j].asset
	})
	return keys
}

// buildTotalRows 按账户、资产排序输出单侧汇总；净扣款 = 扣款 - 退款。
func buildTotalRows(side reconSide) []ReconTotalRow {
	keys := allKeys(side, reconSide{})
	out := make([]ReconTotalRow, 0, len(keys))
	for _, k := range keys {
		charged := new(big.Int)
		if x := side.charged[k]; x != nil {
			charged.Set(x)
		}
		refunded := new(big.Int)
		if x := side.refunded[k]; x != nil {
			refunded.Set(x)
		}
		net := new(big.Int).Sub(new(big.Int).Set(charged), refunded)
		out = append(out, ReconTotalRow{
			Account:       k.account,
			Asset:         k.asset,
			ChargedTotal:  charged.String(),
			RefundedTotal: refunded.String(),
			NetCharged:    net.String(),
		})
	}
	return out
}

// buildNetDiff 输出每个（任一侧出现过的）组合的净扣款差额，方向为流水减账本。
func buildNetDiff(ledger, flow reconSide) []ReconNetDiff {
	out := make([]ReconNetDiff, 0)
	for _, k := range allKeys(ledger, flow) {
		lNet := sideNet(ledger, k)
		fNet := sideNet(flow, k)
		diff := new(big.Int).Sub(new(big.Int).Set(fNet), lNet)
		out = append(out, ReconNetDiff{
			Account:          k.account,
			Asset:            k.asset,
			LedgerNetCharged: lNet.String(),
			FlowNetCharged:   fNet.String(),
			NetChargedDiff:   diff.String(),
		})
	}
	return out
}

