		Limits: []ChargeLimit{limit("aa", "usdc", 6)},
		Intents: []PaymentIntent{
			intent("p1", "aa", "usdc", 8), // 超限且余额不足：报告超限
			intent("p2", "aa", "usdc", 6), // 限额内但余额不足：报告余额
		},
	})
