func TestChargeLimitFailuresDoNotConsumeQuota(t *testing.T) {
	path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 150}})
	l := openOrFail(t, path)

	res, err := l.Submit(FeeBatch{
