		Limits: []ChargeLimit{limit("aa", "usdc", 200)},
		Intents: []PaymentIntent{
			intent("p1", "aa", "usdc", 100), // 成功，已用 100，余额 50
			intent("p2", "aa", "usdc", 100), // 限额内但余额不足，不占额度
			intent("p3", "aa", "usdc", 100), // 若 p2 占了额度此处会报超限
			intent("p4", "aa", "usdc", 50),  // 成功
		},
	})
	if err != nil {
		t.Fatal(err)
