func TestCLISubmitDryRunMissingLedger(t *testing.T) {
	missing := t.TempDir() + "/nope.json"
	r := runCLIWith(t, []string{"submit", "--dry-run", "-l", missing}, `{"fee_bps":0,"intents":[]}`)
